<?php
declare(strict_types=1);
// Included by run.php; every fixture lives in its disposable database.
use Chengyu\Core\{Input,Problem,Migrations,Markdown};
use Chengyu\Services\{Commerce,Media};
function fixtureUser(string $prefix='new'):int {global $a;$name=$prefix.substr(key32(),0,8);return $a->db->insert('cy_users',['username'=>$name,'email'=>$name.'@example.test','password_hash'=>'test-fixture','display_name'=>$name,'role'=>'user','status'=>'active','bio'=>'','created_at'=>time()]);}
function contentInput(int $id,array $changes=[]):array {global $a;$row=$a->db->one('SELECT * FROM cy_contents WHERE id=?',[$id]);$row['price']=$row['price_currency']==='balance'?\Chengyu\Services\Payment::decimal((int)$row['price_amount']):(int)$row['price_amount'];$row['publish_at']=$row['publish_at']?date('Y-m-d H:i:s',(int)$row['publish_at']):'';return array_merge($row,$changes);}
function fixtureVariant(int $product,string $name='Blue',int $stock=3,string $price='2.00'):int {global $a,$admin;return $a->inventory->save($admin,['content_id'=>$product,'sku'=>'SKU-'.key32(),'name'=>$name,'price'=>$price,'inventory'=>$stock,'active'=>'1']);}
$guestBuyer=fixtureUser('buyer');$a->wallet->adjust($guestBuyer,'balance',100000,'ext-funds:'.$guestBuyer,'Extension fixtures');
test('migration is additive, repeatable and versioned',static function()use($a,$config){$before=(int)$a->db->value('SELECT COUNT(*) FROM cy_orders');Migrations::upgrade($a->db,$config['storage']);Migrations::upgrade($a->db,$config['storage']);same(Migrations::VERSION,Migrations::version($a->db));same($before,(int)$a->db->value('SELECT COUNT(*) FROM cy_orders'));truth((bool)$a->db->one('SELECT name FROM cy_settings WHERE name=?',['_schema_version']));});
foreach(['public','login','reply','vip','password'] as $accessMode){test('direct zero-price purchase cannot unlock '.$accessMode,static function()use($a,$admin,$guestBuyer,$accessMode){$id=$a->content->save(account($admin),['kind'=>'article','title'=>'Gate test '.$accessMode,'body'=>'public','protected_body'=>'GATED','status'=>'published','access_level'=>$accessMode,'content_password'=>'secret-password'],true);$before=(int)$a->db->value('SELECT COUNT(*) FROM cy_orders');reject(static function()use($a,$guestBuyer,$id){$a->commerce->buy($guestBuyer,'content',$id,key32());},403);same($before,(int)$a->db->value('SELECT COUNT(*) FROM cy_orders'));});}
test('legacy zero-price order does not bypass VIP policy',static function()use($a,$admin,$guestBuyer){$id=$a->content->save(account($admin),['kind'=>'article','title'=>'Legacy zero order','body'=>'public','protected_body'=>'VIP','status'=>'published','access_level'=>'vip'],true);$row=Commerce::row($guestBuyer,'content',$id,'legacy',0,'balance',key32());$row['status']='paid';$a->db->insert('cy_orders',$row);same(false,$a->content->access($a->content->get($id),account($guestBuyer)));});
foreach([['bad'],"bad\0password"] as $bad){test('malformed password input is a controlled rejection '.gettype($bad),static function()use($bad){reject(static function()use($bad){Input::password($bad);});reject(static function()use($bad){Input::passwordValue($bad);});});}
test('password whitespace is preserved',static function(){same(' password1234 ',Input::passwordValue(' password1234 '));});
$pw=$a->content->save(account($admin),['kind'=>'article','title'=>'Password gate','body'=>'public','protected_body'=>'PW-PRIVATE','access_level'=>'password','content_password'=>' secret1234 ','status'=>'published'],true);
test('guest password access uses exact password',static function()use($a,$pw){same(false,$a->content->access($a->content->get($pw),null));reject(static function()use($a,$pw){$a->content->unlock($pw,'secret1234',null);},403);$a->content->unlock($pw,' secret1234 ',null);truth($a->content->access($a->content->get($pw),null));});
test('changing password revokes previous browser grant',static function()use($a,$admin,$pw){$a->content->save(account($admin),contentInput($pw,['content_password'=>'changed-secret']),true);same(false,$a->content->access($a->content->get($pw),null));});
