test('tier 1 cannot open tier 2 content',static function()use($a,$admin,$tierUser){$id=$a->content->save(account($admin),['kind'=>'article','title'=>'Tier two','body'=>'public','protected_body'=>'private','status'=>'published','access_level'=>'vip','min_vip_tier'=>2],true);same(false,$a->content->access($a->content->get($id),account($tierUser)));$a->membership->grant($tierUser,2,1);truth($a->content->access($a->content->get($id),account($tierUser)));});
