test('shipment can be corrected and owner can confirm receipt',static function()use($a,$admin,$guestBuyer,$checkoutOrders){$id=$checkoutOrders[0];reject(static function()use($a,$guestBuyer,$id){$a->commerce->receive($guestBuyer,$id);});$a->commerce->ship($admin,$id,'TRACK-OLD');$a->commerce->ship($admin,$id,'TRACK-CORRECTED');$a->commerce->receive($guestBuyer,$id);$a->commerce->receive($guestBuyer,$id);same('received',$a->db->value('SELECT fulfillment FROM cy_orders WHERE id=?',[$id]));});
test('withdrawn referral commission does not block buyer refund',static function()use($a,$admin){$ref=fixtureUser('ref');$buyer=fixtureUser('refbuy');$a->db->update('cy_users',$buyer,['referred_by'=>$ref]);$a->wallet->adjust($buyer,'balance',10000,'refund-funds:'.$buyer,'fixture');$product=product('digital','balance','50.00');$order=$a->commerce->buy($buyer,'content',$product,key32());$earned=funds($ref,'commission');truth($earned>0);$a->wallet->adjust($ref,'commission',-$earned,'payout-simulated:'.$ref,'Simulated reserved payout');$a->commerce->requestRefund($buyer,(int)$order['id'],'refund');$a->commerce->refund($admin,(int)$order['id'],true);same(10000,funds($buyer));same(-$earned,funds($ref,'commission'));$a->wallet->adjust($ref,'commission',1,'debt-repayment:'.$ref,'Offset commission debt');same(1-$earned,funds($ref,'commission'));});
test('revision saves old text and rejects stale editor version',static function()use($a,$admin,$pw){$before=contentInput($pw);$a->content->save(account($admin),array_merge($before,['body'=>'CHANGED BODY']),true);reject(static function()use($a,$admin,$before){$a->content->save(account($admin),$before,true);},409);$snapshot=json_decode($a->db->value('SELECT snapshot FROM cy_revisions WHERE content_id=? ORDER BY id DESC LIMIT 1',[$pw]),true);same($before['body'],$snapshot['body']);});
