test('comment visibility rejects unauthorized readers and writers',static function()use($a,$guestBuyer){settings('community',['comment_visibility'=>'verified']);same(false,$a->content->commentsVisible(account($guestBuyer)));same(false,$a->content->commentsVisible(null));reject(static function()use($a,$guestBuyer){$a->content->comment(account($guestBuyer),1,'blocked');},403);settings('community',['comment_visibility'=>'public']);});

test('long SKU order labels fit the MySQL title column',static function()use($a,$admin,$guestBuyer,$skuAddress){$id=product('physical');$a->content->save(account($admin),contentInput($id,['title'=>str_repeat('A',255)]),true);$variant=fixtureVariant($id,str_repeat('B',100),1,'1.00');$o=$a->commerce->buy($guestBuyer,'content',$id,key32(),'',$skuAddress,$variant);truth(strlen($o['title'])<=255);});
test('catalog shows actual minimum available variant price',static function()use($a,$skup){$item=$a->content->get($skup);same(2,(int)$item['variant_count']);same(200,(int)$item['variant_min_price']);});
test('UTF-8 body and revision can exceed 64 KB without being shortened',static function()use($a,$admin){$body=str_repeat("\xe4\xb8\xad",30000);$id=$a->content->save(account($admin),['kind'=>'article','title'=>'Long UTF-8 body','body'=>$body,'status'=>'draft'],true);$a->content->save(account($admin),contentInput($id,['body'=>$body.' revised']),true);$revision=$a->db->one('SELECT snapshot FROM cy_revisions WHERE content_id=?',[$id]);same($body,json_decode($revision['snapshot'],true)['body']);});
// Separate processes contend for the same SKU; each customer has its own wallet and address.
test('eight concurrent SKU purchases settle exactly one unit',static function()use($a,$config,$tmp){
    $pid=product('physical');$variant=fixtureVariant($pid,'One item',1,'1.00');$jobs=[];
    file_put_contents($tmp.'/config.json',json_encode($config));
    for($i=0;$i<8;$i++){$buyer=fixtureUser('sku_race');$a->wallet->adjust($buyer,'balance',1000,'sku-race:'.$buyer,'Concurrency fixture');$address=$a->db->insert('cy_addresses',['user_id'=>$buyer,'recipient'=>'Fixture','phone'=>'000','address'=>'Fixture','created_at'=>time()]);$p=proc_open([PHP_BINARY,'-d','ffi.enable=1',__DIR__.'/sku_worker.php',$tmp.'/config.json',(string)$buyer,(string)$pid,(string)$variant,(string)$address],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$p,$pipes,$buyer];}
    $paid=0;$declined=0;foreach($jobs as [$process,$pipes,$buyer]){$output=trim(stream_get_contents($pipes[1]));$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0){throw new RuntimeException($error);}if($output==='paid'){$paid++;same(900,funds($buyer));}elseif($output==='declined'){$declined++;same(1000,funds($buyer));}else{throw new RuntimeException($output);}}
    same(1,$paid);same(7,$declined);same(0,(int)$a->db->value('SELECT inventory FROM cy_variants WHERE id=?',[$variant]));same(1,(int)$a->db->value('SELECT COUNT(*) FROM cy_orders WHERE item_id=?',[$pid]));
});
